using CarRental.Web.Areas.Billing.Data;
using CarRental.Web.Areas.Billing.Services;
using CarRental.Web.Shared.Data;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace CarRental.Web.Areas.Promotions.Controllers;
[ServiceFilter(typeof(BillingAudit))]
[ApiController,Route("api/promotions"),Authorize(Policy="Promotions.Access")]
public class PromotionsController(RentalDbContext db):ControllerBase {
 async Task<string> Revision(Promotion p)=>PromotionRules.Revision(p,await db.Conditions.AsNoTracking().Where(x=>x.PromotionId==p.Id).ToListAsync());
 async Task<Promotion> Lock(string id)=>await db.Promotions.FromSqlInterpolated($"SELECT * FROM KhuyenMai WITH(UPDLOCK,HOLDLOCK) WHERE maKhuyenMai={id}").SingleOrDefaultAsync()??throw new BusinessError("Không tìm thấy chương trình.");
 async Task Verify(Promotion p,string? revision)=>BillingService.Require(!string.IsNullOrWhiteSpace(revision)&&revision==await Revision(p),"Chương trình đã thay đổi. Hãy tải lại trước khi lưu.");
 [HttpGet] public async Task<object> List(string? q,string? status){var rows=await db.Promotions.AsNoTracking().Where(x=>q==null||x.Id.Contains(q)||x.Name.Contains(q)).ToListAsync();var result=new List<object>();foreach(var p in rows){var state=PromotionRules.State(p,DateTime.UtcNow);if(status!=null&&status!=state)continue;result.Add(new {p.Id,p.Name,p.Kind,p.Value,p.Start,p.End,Status=state,p.Description,p.ActualEnd,Revision=await Revision(p),AppliedCount=await db.Applied.CountAsync(x=>x.PromotionId==p.Id)});}return result;}
 [HttpGet("{id}")] public async Task<object> Detail(string id){var p=await db.Promotions.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id)??throw new BusinessError("Không tìm thấy chương trình.");p.Revision=await Revision(p);return new {program=p,status=PromotionRules.State(p,DateTime.UtcNow),conditions=await db.Conditions.AsNoTracking().Where(x=>x.PromotionId==id).ToListAsync(),applied=await db.Applied.AsNoTracking().Where(x=>x.PromotionId==id).ToListAsync()};}
 [HttpPost] public async Task<object> Create(Promotion p){Validate(p);p.Id=p.Id.Trim().ToUpperInvariant();BillingService.Require(p.End>DateTime.UtcNow,"Chương trình mới đã hết hạn.");p.Status=DateTime.UtcNow<p.Start?"SapApDung":"DangApDung";p.ActualEnd=null;db.Add(p);await db.SaveChangesAsync();p.Revision=await Revision(p);return p;}
 static void Validate(Promotion p)=>BillingService.Require(!string.IsNullOrWhiteSpace(p.Id)&&p.Id.Length<=30&&!string.IsNullOrWhiteSpace(p.Name)&&p.Name.Length<=150&&p.End>p.Start&&p.Value>0&&decimal.Round(p.Value,2)==p.Value&&(p.Kind=="SO_TIEN"||p.Kind=="PHAN_TRAM"&&p.Value<=100),"Thông tin khuyến mãi không hợp lệ.");
 [HttpPut("{id}")] public async Task<object> Edit(string id,Promotion p){Validate(p);BillingService.Require(id==p.Id,"Không được đổi mã.");await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var old=await Lock(id);await Verify(old,p.Revision);BillingService.Require(PromotionRules.State(old,DateTime.UtcNow)!="DaKetThuc","Chương trình đã kết thúc.");BillingService.Require(p.Status==old.Status,"Dùng thao tác tạm ngừng, áp dụng lại hoặc kết thúc để đổi trạng thái.");BillingService.Require(p.End>DateTime.UtcNow&&!await db.Conditions.AnyAsync(x=>x.PromotionId==id&&x.Kind=="THOI_DIEM"&&(x.Start<p.Start||x.End>p.End)),"Thời hạn không hợp lệ hoặc không bao phủ điều kiện.");old.Name=p.Name;old.Kind=p.Kind;old.Value=p.Value;old.Start=p.Start;old.End=p.End;old.Description=p.Description;await db.SaveChangesAsync();await tx.CommitAsync();old.Revision=await Revision(old);return old;}
 public record Transition(string Action,string Revision);
 [HttpPost("{id}/state")] public async Task<object> State(string id,Transition r){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var p=await Lock(id);await Verify(p,r.Revision);var state=PromotionRules.State(p,DateTime.UtcNow);BillingService.Require(state!="DaKetThuc","Chương trình đã kết thúc.");if(r.Action=="pause"){BillingService.Require(state=="DangApDung","Chỉ tạm ngừng chương trình đang áp dụng.");p.Status="TamNgung";}else if(r.Action=="resume"){BillingService.Require(state=="TamNgung"&&DateTime.UtcNow>=p.Start,"Chỉ áp dụng lại chương trình tạm ngừng còn thời hạn.");p.Status="DangApDung";}else if(r.Action=="end"){p.Status="DaKetThuc";p.ActualEnd=DateTime.UtcNow;}else throw new BusinessError("Thao tác không hợp lệ.");await db.SaveChangesAsync();await tx.CommitAsync();return p;}
 [HttpDelete("{id}")] public async Task<object> Delete(string id,string revision){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var p=await Lock(id);await Verify(p,revision);BillingService.Require(PromotionRules.State(p,DateTime.UtcNow)=="SapApDung"&&!await db.Applied.AnyAsync(x=>x.PromotionId==id),"Chỉ xóa chương trình chưa áp dụng.");db.Conditions.RemoveRange(await db.Conditions.Where(x=>x.PromotionId==id).ToListAsync());db.Remove(p);await db.SaveChangesAsync();await tx.CommitAsync();return p;}
 [HttpGet("{id}/conditions")] public async Task<object> Conditions(string id)=>await db.Conditions.AsNoTracking().Where(x=>x.PromotionId==id).ToListAsync();
 [HttpPut("{id}/conditions")] public async Task<object> Conditions(string id,PromotionCondition[] rules,string revision){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var p=await Lock(id);await Verify(p,revision);BillingService.Require(PromotionRules.State(p,DateTime.UtcNow)!="DaKetThuc","Chương trình đã kết thúc.");foreach(var r in rules){BillingService.Require(r.Kind=="NHOM_KHACH"?!string.IsNullOrWhiteSpace(r.Group)&&r.Season==null&&r.Start==null&&r.End==null:r.Kind=="MUA_VU"?!string.IsNullOrWhiteSpace(r.Season)&&r.Group==null&&r.Start==null&&r.End==null:r.Kind=="THOI_DIEM"&&r.Group==null&&r.Season==null&&r.Start>=p.Start&&r.End<=p.End&&r.End>r.Start,"Điều kiện không hợp lệ.");r.Id=0;r.PromotionId=id;}db.Conditions.RemoveRange(await db.Conditions.Where(x=>x.PromotionId==id).ToListAsync());db.AddRange(rules);await db.SaveChangesAsync();await tx.CommitAsync();return rules;}
 [HttpGet("applied")] public async Task<object> Applied()=>await db.Applied.AsNoTracking().ToListAsync();
}
